function simulatePlanetaryFormation(initialDisk, simulationTime):
    particles = initializeDiskParticles(initialDisk)

    for t = 0 to simulationTime with dt:
        // Calcular fuerzas gravitacionales
        for each particle i:
            force[i] = zero_vector
            for each particle j != i:
                r = position[j] - position[i]
                force[i] += G * mass[i] * mass[j] * normalize(r) / |r|²

        // Actualizar posiciones (integración Verlet)
        for each particle i:
            acceleration = force[i] / mass[i]
            velocity[i] += acceleration * dt
            position[i] += velocity[i] * dt

        // Detectar colisiones y acretar
        for each pair (i, j):
            if distance(position[i], position[j]) < (radius[i] + radius[j]):
                // Colisión inelástica: conservar momentum
                newMass = mass[i] + mass[j]
                newVelocity = (mass[i]*velocity[i] + mass[j]*velocity[j]) / newMass
                newPosition = (mass[i]*position[i] + mass[j]*position[j]) / newMass
                newRadius = (radius[i]³ + radius[j]³)^(1/3)

                // Fusionar partículas
                mass[i] = newMass
                velocity[i] = newVelocity
                position[i] = newPosition
                radius[i] = newRadius
                remove(particles, j)

        // Aplicar arrastre del disco (fricción)
        for each particle i:
            velocity[i] *= (1 - dragCoefficient * dt)

    return particles
